import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第五十三卦 渐 风山渐 巽上艮下","description":"周易 - 第五十三卦 渐 风山渐 巽上艮下","frontmatter":{"title":"第五十三卦 渐 风山渐 巽上艮下","description":"周易 - 第五十三卦 渐 风山渐 巽上艮下"},"headers":[],"relativePath":"zh/classics/zhouyi/054.md","filePath":"zh/classics/zhouyi/054.md"}'),l={name:"zh/classics/zhouyi/054.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="渐" tabindex="-1">渐 <a class="header-anchor" href="#渐" aria-label="Permalink to “渐”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>女归吉，利贞。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>渐之进也，女归吉也。进得位，往有功也。进以正，可以正邦也。其位刚，得中也。止而巽，动不穷也。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>山上有木，渐；君子以居贤德，善俗。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>鸿渐于干，小子厉，有言，无咎。 象曰：小子之厉，义无咎也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>鸿渐于磐，饮食衍衍，吉。象曰：饮食衍衍，不素饱也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>鸿渐于陆，夫征不复，妇孕不育，凶；利御寇。象曰：夫征不复，离群丑也。妇孕不育，失其道也。利用御寇，顺相保也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>鸿渐于木，或得其桷，无咎。象曰：或得其桷，顺以巽也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>鸿渐于陵，妇三岁不孕，终莫之胜，吉。象曰：终莫之胜，吉；得所愿也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>鸿渐于逵，其羽可用为仪，吉。象曰：其羽可用为仪，吉；不可乱也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
